    SELECT jsonb_build_object('id', p.id, 'code', p.plan_code, 'productId', p.product_id,
      'audiences', to_jsonb(p.applicable_entities), 'configuration', p.entity_config) INTO STRICT canonical
    FROM public.plans p WHERE p.id = (item->>'plan_id')::uuid;
    PERFORM public.publish_subscription_plan_revision((item->>'plan_id')::uuid, (item->>'revision_id')::uuid,
      NULL, (item->>'published_by')::uuid, canonical);
    SELECT * INTO STRICT stored FROM public.subscription_plan_publication_events
      WHERE plan_id = (item->>'plan_id')::uuid AND revision_id = (item->>'revision_id')::uuid;
    IF stored.canonical_plan IS DISTINCT FROM canonical OR stored.previous_revision_id IS NOT NULL
      OR stored.published_by::text IS DISTINCT FROM item->>'published_by'
    THEN RAISE EXCEPTION 'Subscription bootstrap publication differs'; END IF;
  END LOOP;
